- RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN = b'RCKZGCBATCH__V1_'
- FIELD_ELEMENTS_PER_BLOB (4096)
- FIELD_ELEMENTS_PER_CELL
- len(commitments)
